import ctypes import numpy as np

def numpy_to_gsl_matrix(np_array):
    rows, cols = np_array.shape
    gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(gsl_matrix, i, j, np_array[i, j])
    return gsl_matrix

def numpy_to_gsl_vector(np_array):
    size = np_array.size
    gsl_vector = gsl.gsl_vector_alloc(size)
    for i in range(size):
        gsl.gsl_vector_set(gsl_vector, i, np_array[i])
    return gsl_vector

def compute_gensymm_eigenvalues(A, B):
    if A.shape != B.shape:\n        raise ValueError('Matrices A and B must have the same dimensions.')
    rows, _ = A.shape
    workspace = gsl.gsl_eigen_gensymm_workspace_alloc(rows)
